SELECT u.user_idx, u.user_id, u.user_email, u.nickname, u.account_status, u.user_role, u.created_at, u.last_login_at, u.admin_organization, u.admin_department, u.admin_team, u.admin_title, u.admin_permission_code, m.nickname AS manager_nickname FROM USERS u LEFT JOIN USERS m ON u.admin_manager = m.user_idx WHERE u.user_role = 'ADMIN'
AND u.user_id LIKE CONCAT('%', #{keyword}, '%') AND u.nickname LIKE CONCAT('%', #{keyword}, '%') AND u.user_email LIKE CONCAT('%', #{keyword}, '%')
AND (u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.user_email LIKE CONCAT('%', #{keyword}, '%'))
AND u.admin_department = #{filterDepartment}
AND u.admin_permission_code = #{filterPermissionCode}
AND u.account_status = #{filterAccountStatus}
ORDER BY u.created_at DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM USERS u WHERE u.user_role = 'ADMIN'
AND u.user_id LIKE CONCAT('%', #{keyword}, '%') AND u.nickname LIKE CONCAT('%', #{keyword}, '%') AND u.user_email LIKE CONCAT('%', #{keyword}, '%')
AND (u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.user_email LIKE CONCAT('%', #{keyword}, '%'))
AND u.admin_department = #{filterDepartment}
AND u.admin_permission_code = #{filterPermissionCode}
AND u.account_status = #{filterAccountStatus}

SELECT user_idx, user_id, user_email, nickname, account_status, user_role, created_at FROM USERS WHERE user_role = 'ADMIN'
AND (user_id LIKE CONCAT('%', #{keyword}, '%') OR nickname LIKE CONCAT('%', #{keyword}, '%'))
AND user_idx NOT IN ( SELECT user_idx FROM ADMIN_PERMISSION WHERE permission_code = #{excludePermissionCode} AND is_active = 1 )
AND user_idx NOT IN ( SELECT user_idx FROM ADMIN_PERMISSION_GROUP WHERE group_code = #{excludeGroupCode} AND is_active = 1 )
AND admin_permission_code != #{excludeTemplateCode}
ORDER BY nickname LIMIT #{pageSize} OFFSET #{offset}

